package glitch

import data.glitch_lib

# Define the credential-related keywords to detect empty passwords
credential_keywords := {"password", "pass", "pwd", "secret", "token", "api_key", "credential", "auth", "bindPassword", "bindCredential", "db_password", "mysql_password"}

# Helper to check if a string value is empty
is_empty_string(node) {
    node.ir_type == "String"
    node.value == ""
}

# Helper to check if a string value is null or undefined
is_null_or_undefined(node) {
    node.ir_type == "Null"
}

is_null_or_undefined(node) {
    node.ir_type == "Undef"
}

# Helper to check if an attribute name is credential-related (case-insensitive)
is_credential_attribute(name) {
    lower_name := lower(name)
    some kw
    credential_keywords[kw]
    contains(lower_name, kw)
}

# Check for empty string assignment in attributes or variables
check_empty_value(value) {
    is_empty_string(value)
} else {
    is_null_or_undefined(value)
}

Glitch_Analysis[result] {
    # Gather all unit blocks
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes in atomic units (e.g., resources)
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name is credential-related
    is_credential_attribute(attr.name)

    # Check if the value is empty
    check_empty_value(attr.value)

    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration file - Avoid setting credentials to empty values. (CWE-258)"
    }
}

Glitch_Analysis[result] {
